<span class="line">    <span class="token identifier"><span class="token punctuation">\`</span>trade_time<span class="token punctuation">\`</span></span> <span class="token keyword">DATETIME</span> <span class="token operator">NOT</span> <span class="token boolean">NULL</span> <span class="token keyword">DEFAULT</span> <span class="token keyword">CURRENT_TIMESTAMP</span> <span class="token keyword">COMMENT</span> <span class="token string">&#39;交易时间&#39;</span><span class="token punctuation">,</span></span>
